daemon.after:
ack_text() {
    # Normal validated fields need no four tr processes before each progress/terminal ACK.
    case "$1$2$3$4" in
        *[!A-Za-z0-9._=:/-]*) ;;
        *) printf '%s|%s|%s|%s\n' "$1" "$2" "$3" "$4"; return ;;
    esac
    printf '%s|%s|%s|%s\n' \
        "$(sanitize_ack_field "$1")" \
        "$(sanitize_ack_field "$2")" \
        "$(sanitize_ack_field "$3")" \
        "$(sanitize_ack_field "$4")"
}

publish_request_progress() {
    [ -n "$CURRENT_REQUEST_ID" ] && [ -n "$CURRENT_REQUEST_CMD" ] || return 0
    # Profile publication is the authoritative quick-control ACK. Avoid two earlier Settings writes.
    case "$CURRENT_REQUEST_CMD" in set_uperf_app|set_uperf_mode|remove_uperf_app) return 0 ;; esac
    publish_request_ack "$CURRENT_REQUEST_ID" processing "$CURRENT_REQUEST_CMD" "$1"
}

count_request_fields() {
    count_tail="${1%%'
'*}"
    [ -n "$count_tail" ] || { field_count=0; return; }
    field_count=1
    while :; do
        case "$count_tail" in *'|'*) field_count=$((field_count + 1)); count_tail="${count_tail#*'|'}" ;; *) break ;; esac
    done
}

request_field_count() {
    count_request_fields "$1"
    printf '%s\n' "$field_count"
}
